css:
:root:not(.dark){--gb-bubble:#FFFFFF;--gb-line:#ECECEC;--gb-btn:#F0F0F0;--gb-btn-hover:#E6E6E6;--gb-shadow:rgba(0,0,0,.08);--gb-composer:#FFFFFF;--gb-composer-line:#E6E6E6;--gb-sidebar:#F3F3F3;--gb-edge:#ECECEC}
.dark{--gb-bubble:#1C1C1C;--gb-line:#242424;--gb-btn:#1E1E1E;--gb-btn-hover:#2A2A2A;--gb-shadow:rgba(0,0,0,.5);--gb-composer:#1F1F1F;--gb-composer-line:#262626;--gb-sidebar:#0E0E0E;--gb-edge:#151515}
body{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}
.surface-grain{background-image:none!important}
[data-slot="sidebar-inner"]{background-color:var(--gb-sidebar)!important}
[data-slot="sidebar-container"]{border:0!important;box-shadow:inset -1px 0 0 var(--gb-edge)!important}
[data-sidebar-row]{border-radius:12px!important}
[data-slot="button"],[data-slot="select-trigger"],[data-slot="input"]{border-radius:9999px!important;transition:background-color .15s,border-color .15s,color .15s}
[data-slot="dialog-popup"],[data-thread-details-card]{border-radius:24px!important}
[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:16px!important}
[data-slot="tooltip-popup"]{border-radius:10px!important}
[data-user-message-bubble]{border-radius:20px!important}
[data-message-role="assistant"] .chat-markdown{background:var(--gb-bubble);border:1px solid var(--gb-line);border-radius:20px;padding:12px 16px;width:fit-content;max-width:100%;box-sizing:border-box}
[data-message-role="assistant"] .chat-markdown .chat-markdown{background:none;border:0;padding:0;border-radius:0}
.chat-markdown-codeblock{border-radius:14px!important}
[data-chat-composer-form],[data-slot="composer-shell"],[data-slot="composer-host"],[data-chat-composer-main-surface]{--chat-composer-glass-surface:var(--gb-composer)!important;--chat-composer-outline:var(--gb-composer-line)!important;--chat-composer-highlight:transparent!important;--glass-opacity:100%!important}
[data-slot="composer-shell"],[data-slot="composer-shell"]::before,[data-slot="composer-host"],[data-slot="composer-host"]::before,[data-slot="composer-host"]::after,[data-chat-composer-main-surface],[data-chat-composer-main-surface]::after,[data-chat-composer-surface]{border-radius:28px!important}
[data-slot="composer-host"]{background:var(--gb-composer)!important;box-shadow:none!important}
[data-slot="composer-host"]::after{border-color:var(--gb-composer-line)!important;box-shadow:none!important}
[data-chat-composer-footer]{padding:0 10px 10px!important}
[data-chat-composer-form] button{border-radius:9999px!important}
svg.lucide{stroke-width:1.75}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--gb-btn-hover);border-radius:9999px;border:3px solid transparent;background-clip:padding-box}
[data-slot="scroll-area-thumb"]{border-radius:9999px!important}
[data-sidebar-row]{transition:background-color .12s}
:root:not(.dark) [data-chat-header]{background:rgba(250,250,250,.72)!important}
.dark [data-chat-header]{background:rgba(18,18,18,.72)!important}
[data-chat-header]{backdrop-filter:blur(14px) saturate(140%);-webkit-backdrop-filter:blur(14px) saturate(140%)}
[data-chat-header] [data-slot="button"]{background:var(--gb-btn);border:1px solid var(--gb-btn-hover)}
[data-chat-header] [data-slot="button"]:hover{background:var(--gb-btn-hover)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{box-shadow:0 20px 60px var(--gb-shadow)!important}
[data-timeline-row-kind="work"]{opacity:.85}
::selection{background:rgba(76,155,255,.35)}
:root:not(.dark){--gb-on:#326CCB;--gb-off:#E2E2E2;--gb-knob:#FFFFFF}
.dark{--gb-on:#326CCB;--gb-off:#2A2A2A;--gb-knob:#F5F5F5}
[data-slot="switch"][data-checked]{background:var(--gb-on)!important}
[data-slot="switch"][data-unchecked],[data-slot="switch"][data-mixed]{background:var(--gb-off)!important}
[data-slot="switch-thumb"]{background:var(--gb-knob)!important;box-shadow:0 1px 3px rgba(0,0,0,.3)!important}
.settings-slider::-webkit-slider-runnable-track{background:linear-gradient(to right,var(--gb-on) 0 var(--settings-slider-fill-position),var(--gb-off) var(--settings-slider-fill-position) 100%)!important;box-shadow:none!important}
.settings-slider::-webkit-slider-thumb{background:var(--gb-knob)!important;border:0!important;box-shadow:0 1px 4px rgba(0,0,0,.4)!important}
:root:not(.dark){--gb-pill:#EDEDED;--gb-draft:#0A0A0A}
.dark{--gb-pill:#272727;--gb-draft:#F2F2F2}
[data-slot="voice-input-pill"]{box-shadow:none!important;--tw-ring-shadow:0 0 #0000!important}
[data-slot="voice-input-pill"]:not([class*="destructive"]){background:var(--gb-pill)!important}
[data-sidebar-row] .text-warning-foreground{color:var(--gb-draft)!important}
